CREATE TABLE public.loot_players (user_id uuid PRIMARY KEY, display_name text NOT NULL DEFAULT 'Player', spins integer NOT NULL DEFAULT 50, tickets integer NOT NULL DEFAULT 1, regenerated_at timestamptz NOT NULL DEFAULT now(), last_played_at timestamptz);
GRANT SELECT ON public.loot_players TO authenticated;
GRANT ALL ON public.loot_players TO service_role;
ALTER TABLE public.loot_players ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own competition wallet" ON public.loot_players FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.loot_scores (run bigint NOT NULL, user_id uuid NOT NULL, display_name text NOT NULL, tokens bigint NOT NULL DEFAULT 0, PRIMARY KEY(run,user_id));
GRANT SELECT ON public.loot_scores TO authenticated;
GRANT ALL ON public.loot_scores TO service_role;
ALTER TABLE public.loot_scores ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read competition standings" ON public.loot_scores FOR SELECT TO authenticated USING (true);
CREATE TABLE public.loot_awards (run bigint NOT NULL, user_id uuid NOT NULL, rank integer NOT NULL, spins integer NOT NULL, tickets integer NOT NULL, claimed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run,user_id));
GRANT SELECT ON public.loot_awards TO authenticated;
GRANT ALL ON public.loot_awards TO service_role;
ALTER TABLE public.loot_awards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own rank awards" ON public.loot_awards FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.loot_prize(p_rank integer) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN p_rank=1 THEN jsonb_build_object('spins',5000,'tickets',50) WHEN p_rank=2 THEN jsonb_build_object('spins',3000,'tickets',30) WHEN p_rank=3 THEN jsonb_build_object('spins',2000,'tickets',20) WHEN p_rank BETWEEN 4 AND 10 THEN jsonb_build_object('spins',1000,'tickets',10) ELSE jsonb_build_object('spins',0,'tickets',0) END $$;
CREATE FUNCTION public.loot_join() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); r bigint:=floor((extract(epoch from now())+14400)/86400); n text; w public.loot_players; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; n:='Player '||left(u::text,6); INSERT INTO public.loot_players(user_id,display_name) VALUES(u,n) ON CONFLICT DO NOTHING; SELECT * INTO w FROM public.loot_players WHERE user_id=u; INSERT INTO public.loot_scores(run,user_id,display_name) VALUES(r,u,w.display_name) ON CONFLICT DO NOTHING; RETURN jsonb_build_object('spins',w.spins,'tickets',w.tickets,'run',r); END $$;
REVOKE ALL ON FUNCTION public.loot_join() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.loot_join() TO authenticated;
CREATE FUNCTION public.loot_play(p_bet integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); w public.loot_players; r bigint:=floor((extract(epoch from now())+14400)/86400); cells text[]:=ARRAY[]::text[]; v float; c text; i integer; hits integer:=0; added integer:=0; wheel_added integer:=0; count_same integer; g integer; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF p_bet NOT IN (1,2,3,5,10,20,50) THEN RAISE EXCEPTION 'Invalid bet'; END IF; SELECT * INTO w FROM public.loot_players WHERE user_id=u FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Join first'; END IF; IF w.last_played_at > now()-interval '1400 milliseconds' THEN RAISE EXCEPTION 'Wait for current spin'; END IF; g:=greatest(0,floor(extract(epoch from now()-w.regenerated_at)/60)); IF w.spins<50 THEN w.spins:=least(50,w.spins+g); END IF; IF w.spins<p_bet THEN RAISE EXCEPTION 'Not enough spins'; END IF; FOR i IN 1..3 LOOP v:=random()*100; c:=CASE WHEN v<30 THEN 'coin' WHEN v<52 THEN 'bolt' WHEN v<62 THEN 'wheel' WHEN v<76 THEN 'chest' WHEN v<80 THEN 'gem' WHEN v<90 THEN 'token' WHEN v<95 THEN 'neon-soda' ELSE 'robot' END; cells:=array_append(cells,c); IF c='robot' THEN hits:=hits+p_bet; END IF; END LOOP; SELECT count(*) INTO count_same FROM unnest(cells) t WHERE t='bolt'; added:=CASE WHEN count_same=3 THEN 25*p_bet WHEN count_same=2 THEN 3*p_bet ELSE 0 END; SELECT count(*) INTO count_same FROM unnest(cells) t WHERE t='wheel'; wheel_added:=CASE WHEN count_same=3 THEN 3*p_bet WHEN count_same=2 THEN p_bet ELSE 0 END; UPDATE public.loot_players SET spins=w.spins-p_bet+added,tickets=w.tickets+wheel_added,last_played_at=now(),regenerated_at=CASE WHEN g>0 OR w.spins>=50 THEN now() ELSE regenerated_at END WHERE user_id=u; INSERT INTO public.loot_scores(run,user_id,display_name,tokens) VALUES(r,u,w.display_name,hits) ON CONFLICT(run,user_id) DO UPDATE SET tokens=public.loot_scores.tokens+excluded.tokens; RETURN jsonb_build_object('cells',cells,'spins',w.spins-p_bet+added,'tickets',w.tickets+wheel_added,'tokens',hits,'run',r); END $$;
REVOKE ALL ON FUNCTION public.loot_play(integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.loot_play(integer) TO authenticated;
CREATE FUNCTION public.loot_claim(p_run bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); cur bigint:=floor((extract(epoch from now())+14400)/86400); pos integer; prize jsonb; inserted integer; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF p_run>=cur THEN RAISE EXCEPTION 'Event has not ended'; END IF; SELECT rank INTO pos FROM (SELECT user_id,row_number() OVER(ORDER BY tokens DESC,user_id) AS rank FROM public.loot_scores WHERE run=p_run AND tokens>0) t WHERE user_id=u; IF pos IS NULL OR pos>10 THEN RAISE EXCEPTION 'No rank reward'; END IF; prize:=public.loot_prize(pos); INSERT INTO public.loot_awards(run,user_id,rank,spins,tickets) VALUES(p_run,u,pos,(prize->>'spins')::integer,(prize->>'tickets')::integer) ON CONFLICT DO NOTHING; GET DIAGNOSTICS inserted=ROW_COUNT; IF inserted=0 THEN RAISE EXCEPTION 'Reward already claimed'; END IF; UPDATE public.loot_players SET spins=spins+(prize->>'spins')::integer,tickets=tickets+(prize->>'tickets')::integer WHERE user_id=u; RETURN prize||jsonb_build_object('rank',pos); END $$;
REVOKE ALL ON FUNCTION public.loot_claim(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.loot_claim(bigint) TO authenticated;